<script setup lang="ts">
import { ref,computed,watch,onMounted } from 'vue';
import { useRoute,useRouter,RouterLink } from 'vue-router';
import { IonPage,IonContent,IonButton,IonSpinner,IonToggle,IonIcon,alertController } from '@ionic/vue';
import { gridOutline,trendingUpOutline,trendingDownOutline,settingsOutline,walletOutline } from 'ionicons/icons';
import VueApexCharts from 'vue3-apexcharts';
import type { ApexOptions } from 'apexcharts';
import PeriodFilter from '../components/PeriodFilter.vue';
import EntryForm from '../components/EntryForm.vue';
import { session,filtered,loadEntries,dark,applyTheme,periodValid } from '../store';
import { money,cents,dateLabel,summarize,type Entry,type Kind } from '../lib/finance';
import { supabase,errorMessage } from '../lib/supabase';
const route=useRoute();const router=useRouter();
const links=[{path:'dashboard',label:'Dashboard',icon:gridOutline},{path:'receitas',label:'Receitas',icon:trendingUpOutline},{path:'despesas',label:'Despesas',icon:trendingDownOutline},{path:'configuracoes',label:'Configurações',icon:settingsOutline}];
const page=computed(()=>String(route.params.page));const title=computed(()=>links.find(l=>l.path===page.value)?.label||'Dashboard');const kind=computed(()=>page.value as Kind);
const loading=ref(false);const error=ref('');const success=ref('');const editing=ref(false);const selected=ref<Entry|null>(null);const removing=ref<string|null>(null);const loggingOut=ref(false);
const summary=computed(()=>summarize(filtered.value.receitas,filtered.value.despesas));
const entries=computed(()=>filtered.value[kind.value]||[]);
const chartBase=computed<ApexOptions>(()=>({theme:{mode:dark.value?'dark':'light'},chart:{background:'transparent',toolbar:{show:false},fontFamily:'inherit'},colors:['#16865d','#dc684d','#5287c6','#c5a24c','#9171b5','#59aaa4','#b57389'],legend:{position:'bottom'},dataLabels:{enabled:false},noData:{text:'Sem lançamentos no período'},tooltip:{y:{formatter:(value:number)=>money(Math.round(value*100))}}}));
const pieOptions=computed<ApexOptions>(()=>({...chartBase.value,labels:Object.keys(summary.value.byCategory),stroke:{width:0}}));
const barOptions=computed<ApexOptions>(()=>({...chartBase.value,colors:['#16865d','#dc684d'],xaxis:{categories:summary.value.months.map(m=>`${m.slice(5)}/${m.slice(0,4)}`)},yaxis:{labels:{formatter:(v:number)=>money(Math.round(v*100))}},plotOptions:{bar:{borderRadius:4,columnWidth:'45%'}}}));
async function refresh(){loading.value=true;error.value='';try{await loadEntries();}catch(e){error.value=errorMessage(e);}finally{loading.value=false;}}
async function saved(){editing.value=false;success.value='Lançamento salvo com sucesso.';await refresh();}
async function remove(entry:Entry){const table=kind.value;const alert=await alertController.create({header:'Excluir lançamento?',message:`Deseja excluir “${entry.descricao}”? Esta ação não pode ser desfeita.`,buttons:[{text:'Cancelar',role:'cancel'},{text:'Excluir',role:'destructive',handler:()=>{void doRemove(entry,table);}}]});await alert.present();}
async function doRemove(entry:Entry,table:Kind){if(removing.value)return;removing.value=entry.id;success.value='';try{const result=await supabase!.from(table).delete().eq('id',entry.id).eq('user_id',session.value!.user.id).select('id').single();if(result.error)throw result.error;success.value='Lançamento excluído.';await refresh();}catch(e){error.value=errorMessage(e);}finally{removing.value=null;}}
async function logout(){if(loggingOut.value)return;loggingOut.value=true;try{const result=await supabase!.auth.signOut();if(result.error)throw result.error;session.value=null;await router.replace('/login');}catch(e){error.value=errorMessage(e);}finally{loggingOut.value=false;}}
watch(page,()=>{editing.value=false;selected.value=null;success.value='';});onMounted(refresh);
</script>
<template><ion-page><ion-content><div class="workspace"><aside class="sidebar"><a class="brand" href="#/dashboard"><ion-icon :icon="walletOutline"/> Meu Dinheiro</a><span class="eyebrow">SEU CONTROLE FINANCEIRO</span><nav><router-link v-for="link in links" :key="link.path" :to="'/'+link.path"><ion-icon :icon="link.icon"/><span>{{link.label}}</span></router-link></nav><div class="sidebar-bottom"><span class="privacy-dot"></span> Um espaço só seu<small>Clareza para suas próximas escolhas.</small></div></aside><main class="main"><header class="topbar"><span>MINHAS FINANÇAS / {{title.toLocaleUpperCase('pt-BR')}}</span><span class="user-email">{{session?.user.email}}</span></header><div class="heading"><div><span class="eyebrow">CADA ESCOLHA CONTA</span><h1>{{page==='dashboard'?'Sua vida financeira, em dia.':title}}</h1><p>{{page==='dashboard'?'Uma visão clara do que entra, do que sai e do que fica.':page==='configuracoes'?'Deixe este espaço do seu jeito.':'Organize seus lançamentos e acompanhe seus movimentos.'}}</p></div><ion-button v-if="page==='receitas'||page==='despesas'" @click="selected=null;editing=true;success=''">+ {{page==='receitas'?'Nova receita':'Nova despesa'}}</ion-button></div><p v-if="error" role="alert" class="notice error">{{error}} <ion-button size="small" fill="clear" @click="refresh">Tentar novamente</ion-button></p><p v-if="success" class="notice" role="status">{{success}}</p><template v-if="page!=='configuracoes'"><period-filter/><div v-if="loading" role="status" class="loading"><ion-spinner/> Atualizando seus lançamentos…</div><template v-else-if="!error && periodValid"><template v-if="page==='dashboard'"><section class="summary-grid"><article class="panel balance"><span>SALDO DO PERÍODO</span><h2>{{money(summary.balance)}}</h2><small>Receitas menos despesas</small></article><article class="panel"><span class="income">↗ TOTAL DE RECEITAS</span><h2>{{money(summary.totalIncome)}}</h2><small>Entradas no período</small></article><article class="panel"><span class="expense">↘ TOTAL DE DESPESAS</span><h2>{{money(summary.totalExpenses)}}</h2><small>Saídas no período</small></article></section><section class="charts-grid"><article class="panel"><h2>Para onde vai seu dinheiro?</h2><p>Despesas por categoria</p><VueApexCharts v-if="Object.keys(summary.byCategory).length" type="donut" height="300" :options="pieOptions" :series="Object.values(summary.byCategory).map(v=>v/100)"/><div v-else class="empty">Ainda não há despesas neste período.</div></article><article class="panel"><h2>Entradas e saídas</h2><p>Compare seus movimentos mês a mês</p><VueApexCharts v-if="summary.months.length" type="bar" height="300" :options="barOptions" :series="summary.series"/><div v-else class="empty">Seus gráficos aparecem quando você adicionar lançamentos.</div></article></section><section class="indicators"><article class="panel"><small>Maior gasto por categoria</small><strong>{{summary.top}}</strong></article><article class="panel"><small>Total de lançamentos</small><strong>{{summary.count}}</strong></article><article class="panel"><small>Despesas em relação às receitas</small><strong>{{summary.percent===null?'Sem receitas no período':summary.percent.toLocaleString('pt-BR',{maximumFractionDigits:1})+'%'}}</strong></article></section></template><template v-else><entry-form v-if="editing" :key="kind+(selected?.id||'new')" :kind="kind" :entry="selected" @saved="saved" @cancel="editing=false"/><section class="panel list"><div class="list-header"><h2>Seus lançamentos</h2><small>{{entries.length}} registro(s)</small></div><div v-if="!entries.length" class="empty"><h3>Um novo começo para suas contas</h3><p>Nenhum lançamento neste período. Use o botão acima para adicionar.</p></div><article class="entry" v-for="entry in entries" :key="entry.id"><span class="entry-icon" :class="kind==='receitas'?'income':'expense'">{{kind==='receitas'?'↗':'↘'}}</span><div class="entry-description"><strong>{{entry.descricao}}</strong><small>{{entry.categoria}} · {{dateLabel(entry.data)}}</small></div><strong :class="kind==='receitas'?'income':'expense'">{{money(cents(entry.valor))}}</strong><div class="entry-actions"><ion-button fill="clear" size="small" :disabled="!!removing" @click="selected=entry;editing=true">Editar</ion-button><ion-button fill="clear" color="danger" size="small" :disabled="!!removing" @click="remove(entry)">Excluir</ion-button></div></article></section></template></template></template><section v-else class="panel settings"><h2>Preferências</h2><div class="setting-row"><div><strong>Modo escuro</strong><p>A preferência fica salva neste dispositivo.</p></div><ion-toggle aria-label="Modo escuro" :checked="dark" @ionChange="dark=$event.detail.checked;applyTheme()"/></div><hr><h2>Sua conta</h2><p>{{session?.user.email}}</p><ion-button color="danger" fill="outline" :disabled="loggingOut" @click="logout">{{loggingOut?'Saindo…':'Sair da conta'}}</ion-button></section><footer>Meu Dinheiro · Mais organização, mais tranquilidade.</footer></main></div></ion-content></ion-page></template>
